INSERT INTO Course VALUES ('DBI202', N'Database Systems', 2), ('CSD201', N'Data Structures', 0), ('PRF192', N'Programming', 30);
INSERT INTO Enrolment VALUES (2, 'DBI202', 8.5), (3, 'PRF192', 6.0), (2, 'PRF192', 9.0);
GO
PRINT N'setup.sql: database DBI202_CL ready.';

-- check.sql — self-check for: A complete procedure: validate, transact, catch, return a code
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 5 checks ──────────';

-- CHECK 1: Success: row inserted, one seat taken, code 0
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN; DECLARE @m NVARCHAR(200), @rc INT; EXEC @rc = dbo.sp_EnrolStudent 1, ''DBI202'', @m OUTPUT;
SET @ok = IIF(@rc = 0 AND @m = N''OK'' AND EXISTS (SELECT 1 FROM Enrolment WHERE sid = 1 AND cid = ''DBI202'') AND (SELECT seats FROM Course WHERE cid = ''DBI202'') = 1, 1, 0);
SET @info = CONCAT(N''rc='', @rc, N'' msg='', @m); IF @@TRANCOUNT > 0 ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. Success: row inserted, one seat taken, code 0 | Thành công: thêm dòng, trừ một chỗ, mã 0'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. Success: row inserted, one seat taken, code 0 | Thành công: thêm dòng, trừ một chỗ, mã 0', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

