WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. Unknown student → 1, unknown course → 2, nothing changes | Sinh viên lạ → 1, môn lạ → 2, không đổi gì'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. Unknown student → 1, unknown course → 2, nothing changes | Sinh viên lạ → 1, môn lạ → 2, không đổi gì', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: Full course (0 seats): code -1 and NO enrolment row left behind
SELECT @ok = 0, @info = NULL;
BEGIN TRY
