  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Full course (0 seats): code -1 and NO enrolment row left behind | Môn hết chỗ (0 chỗ): mã -1 và KHÔNG còn dòng đăng ký nào sót lại'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. Full course (0 seats): code -1 and NO enrolment row left behind | Môn hết chỗ (0 chỗ): mã -1 và KHÔNG còn dòng đăng ký nào sót lại', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

