WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. Already enrolled: code -1, seats unchanged | Đã đăng ký rồi: mã -1, số chỗ không đổi'; END
