    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 5. No transaction is left open after a failure | Không để giao dịch nào mở sau khi lỗi'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 5. No transaction is left open after a failure | Không để giao dịch nào mở sau khi lỗi', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

